68.   public Metrics.MetricFamily convert(MetricSnapshot snapshot, EscapingScheme scheme) {
69.     Metrics.MetricFamily.Builder builder = Metrics.MetricFamily.newBuilder();
70.     if (snapshot instanceof CounterSnapshot) {
