72.         builder.addMetric(convert(data, scheme));
73.       }
74.       setMetadataUnlessEmpty(
75.           builder, snapshot.getMetadata(), "_total", Metrics.MetricType.COUNTER, scheme);
76.     } else if (snapshot instanceof GaugeSnapshot) {
77.       for (GaugeSnapshot.GaugeDataPointSnapshot data : ((GaugeSnapshot) snapshot).getDataPoints()) {
78.         builder.addMetric(convert(data, scheme));
79.       }
80.       setMetadataUnlessEmpty(
81.           builder, snapshot.getMetadata(), null, Metrics.MetricType.GAUGE, scheme);
82.     } else if (snapshot instanceof HistogramSnapshot) {
83.       HistogramSnapshot histogram = (HistogramSnapshot) snapshot;
84.       for (HistogramSnapshot.HistogramDataPointSnapshot data : histogram.getDataPoints()) {
85.         builder.addMetric(convert(data, scheme));
86.       }
87.       Metrics.MetricType type =
88.           histogram.isGaugeHistogram()
89.               ? Metrics.MetricType.GAUGE_HISTOGRAM
90.               : Metrics.MetricType.HISTOGRAM;
91.       setMetadataUnlessEmpty(builder, snapshot.getMetadata(), null, type, scheme);
92.     } else if (snapshot instanceof SummarySnapshot) {
93.       for (SummarySnapshot.SummaryDataPointSnapshot data :
94.           ((SummarySnapshot) snapshot).getDataPoints()) {
95.         if (data.hasCount() || data.hasSum() || data.getQuantiles().size() > 0) {
96.           builder.addMetric(convert(data, scheme));
97.         }
98.       }
99.       setMetadataUnlessEmpty(
100.           builder, snapshot.getMetadata(), null, Metrics.MetricType.SUMMARY, scheme);
101.     } else if (snapshot instanceof InfoSnapshot) {
102.       for (InfoSnapshot.InfoDataPointSnapshot data : ((InfoSnapshot) snapshot).getDataPoints()) {
103.         builder.addMetric(convert(data, scheme));
104.       }
105.       setMetadataUnlessEmpty(
106.           builder, snapshot.getMetadata(), "_info", Metrics.MetricType.GAUGE, scheme);
107.     } else if (snapshot instanceof StateSetSnapshot) {
108.       for (StateSetSnapshot.StateSetDataPointSnapshot data :
109.           ((StateSetSnapshot) snapshot).getDataPoints()) {
110.         for (int i = 0; i < data.size(); i++) {
111.           builder.addMetric(convert(data, snapshot.getMetadata().getPrometheusName(), i, scheme));
112.         }
113.       }
114.       setMetadataUnlessEmpty(
115.           builder, snapshot.getMetadata(), null, Metrics.MetricType.GAUGE, scheme);
116.     } else if (snapshot instanceof UnknownSnapshot) {
117.       for (UnknownSnapshot.UnknownDataPointSnapshot data :
118.           ((UnknownSnapshot) snapshot).getDataPoints()) {
119.         builder.addMetric(convert(data, scheme));
120.       }
121.       setMetadataUnlessEmpty(
122.           builder, snapshot.getMetadata(), null, Metrics.MetricType.UNTYPED, scheme);
